weak_ciphers = {"DES", "RC4", "3DES", "MD5", "SHA1", "CAMELLIA", "ARIA"}

check_weak_algorithm(value) {
    value.ir_type == "String"
    algorithm := lower(value.value)
    algorithm == lower(weak_algorithms[_])
