    attr_name == "key_length"
    value.value < min_symmetric_key
} else {
    value.ir_type == "Integer"
    attr_name == "key_size"
    value.value < min_symmetric_key
} else {
    value.ir_type == "Integer"
    attr_name == "bit_length"
    value.value < min_symmetric_key
} else {
    value.ir_type == "Integer"
    attr_name == "encryption_bits"
    value.value < min_symmetric_key
}

check_protocol(value) {
    value.ir_type == "String"
    deprecated_protocols[value.value]
} else {
    value.ir_type == "Array"
    some element in value.value
    element.ir_type == "String"
    deprecated_protocols[element.value]
}

check_encryption_enabled(value) {
    value.ir_type == "Boolean"
